package net.officefloor.hq.app.watch;

import java.time.LocalDate;
import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The people the signed-in user watches on a sheet. The caller's signed-in name comes in the {@code X-User}
 *  header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class WatchController {

    /** Whether the caller watches a person. */
    public record WatchView(long personId, boolean watched) {
    }

    /** Whether the caller is to watch the person. */
    public record WatchForm(@NotNull Boolean watched) {
    }

    private final WatchService watches;

    private final SheetHistory history;

    public WatchController(WatchService watches, SheetHistory history) {
        this.watches = watches;
        this.history = history;
    }

    /** The ids of the people the caller watches. */
    @GetMapping("/watches")
    public List<Long> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).watches().getOrDefault(user, List.of());
        }
        return watches.list(sheetId, user).stream().map(Watch::getPersonId).toList();
    }

    @PutMapping("/people/{id}/watch")
    public WatchView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody WatchForm request) {
        return new WatchView(id, watches.set(sheetId, user, id, request.watched()));
    }
}
package net.officefloor.hq.app.watch;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user watching a person on a sheet: the user is told whenever one of the person's claims is settled. */
@Entity
@Table(name = "watch")
public class Watch {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    protected Watch() {
    }

    public Watch(String sheetId, Long personId, String userName) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.userName = userName;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getUserName() {
        return userName;
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface WatchRepository extends JpaRepository<Watch, Long> {

    List<Watch> findBySheetIdAndUserNameOrderByIdAsc(String sheetId, String userName);

    List<Watch> findByPersonIdOrderByIdAsc(Long personId);

    List<Watch> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Watch> findByPersonIdAndUserName(Long personId, String userName);
}
package net.officefloor.hq.app.watch;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people each user watches on a sheet, and the notices sent to them. */
@Service
public class WatchService {

    private final WatchRepository watches;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public WatchService(WatchRepository watches, PersonRepository people, SheetService sheets, Audit audit) {
        this.watches = watches;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The people the user watches on the sheet, in the order they started watching. */
    @Transactional(readOnly = true)
    public List<Watch> list(String sheetId, String user) {
        return watches.findBySheetIdAndUserNameOrderByIdAsc(sheetId, user);
    }

    /** Start or stop the user watching the person; refused when the user already does (or does not) watch them. */
    @Transactional
    public boolean set(String sheetId, String user, long personId, boolean watched) {
        sheets.load(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
        if (existing.isPresent() == watched) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    watched ? "You already watch that person" : "You do not watch that person");
        }
        if (watched) {
            try {
                watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
            } catch (DataIntegrityViolationException raced) {
                throw new ResponseStatusException(HttpStatus.CONFLICT, "You already watch that person");
            }
        } else {
            watches.delete(existing.get());
            watches.flush();
        }
        audit.recordChangeOnCommit(sheetId, user, (watched ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName());
        return watched;
    }

    /** Tell each user watching the person that one of their claims was settled, in the order they started
     *  watching. */
    public void notifyWatchers(String sheetId, String user, Person person, String number) {
        for (Watch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + w.getUserName()
                    + " person=" + person.getName() + " number=" + number);
        }
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** Whether the signed-in user watches a person. */
export interface WatchView {
  personId: number;
  watched: boolean;
}

// The people the signed-in user watches on a sheet.
@Injectable({ providedIn: 'root' })
export class Watches {
  private readonly http = inject(HttpClient);

  /** The ids of the people the signed-in user watches. */
  list(sheetId: string): Observable<number[]> {
    return this.http.get<number[]>(`/api/sheets/${encodeURIComponent(sheetId)}/watches`);
  }

  /** Start or stop watching the person; refused when already so. */
  set(sheetId: string, personId: number, watched: boolean): Observable<WatchView> {
    return this.http.put<WatchView>(
      `/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/watch`,
      { watched },
    );
  }
}
